userscript.function:

		for (var i in $options) {
            var tabOptions = $options[i];
            tabbarObj.addTab(tabOptions.id, Sepoa.cache.text.get('AD_406.' + tabOptions.id));
            if (i == 0) {
                tabbarObj.tabs(tabOptions.id).setActive();
            }

            if (tabOptions.items) {
                var formOptions = [{
                        type: "settings",
                        position: "label-top",
                        inputWidth: 120
                    },
                    {
                        type: "block",
                        width: "auto",
                        list: tabOptions.items
                    }
                ]

                for (var i in tabOptions.items) {
                    formOptionBuilder(tabOptions.items[i]);
                }

                var formObj = tabbarObj.tabs(tabOptions.id).attachForm(formOptions);

                if(tabOptions.id == 'SMS'){
                    formObj.attachEvent('onChange', function(id, v){
                        if(id == 'SMS_USE') {
                            if(v == 'true') {
                                this.showItem('SMS_MODULE');
                                this.showItem('SMS_SEPOA_API_OPTIONS');
                            } else {
                                this.hideItem('SMS_MODULE');
                                this.hideItem('SMS_SEPOA_API_OPTIONS');
                                this.hideItem('SMS_CUSTOM_OPTIONS');
                            }
                        } else if(id == 'SMS_MODULE'){
                            if(v == 'sepoaapi'){
                                this.showItem('SMS_SEPOA_API_OPTIONS');
                                this.hideItem('SMS_CUSTOM_OPTIONS');
                            }else{
                                this.showItem('SMS_CUSTOM_OPTIONS');
                                this.hideItem('SMS_SEPOA_API_OPTIONS');
                            }
                        }
                    });
                } else if(tabOptions.id == 'KAKAO') {
                    formObj.attachEvent('onChange', function(id, v){
                        if(id == 'KAKAO_USE') {
                            if(v == 'true') {
                                this.showItem('KAKAO_CUSTOM_USE');
                                this.showItem('KAKAO_BIZPLUS');
                            } else {
                                this.hideItem('KAKAO_CUSTOM_USE');
                                this.hideItem('KAKAO_BIZPLUS');
                                this.hideItem('KAKAO_CUSTOM');
                            }
                        } else if(id == 'KAKAO_CUSTOM_USE') {
                            if(v == 'true') {
                                this.showItem('KAKAO_CUSTOM');
                                this.hideItem('KAKAO_BIZPLUS');
                            } else {
                                this.showItem('KAKAO_BIZPLUS');
                                this.hideItem('KAKAO_CUSTOM');
                            }
                        }
                    });
                } else if(tabOptions.id == 'SMTP') {
                    formObj.attachEvent('onChange', function(id, v){
                        if(id == 'SMTP_USE') {
                            if(v == 'true') {
                                this.showItem('SMTP_CUSTOM_USE');
                                this.showItem('SMTP_DEFAULT_OPTIONS');
                            } else {
                                this.hideItem('SMTP_CUSTOM_USE');
                                this.hideItem('SMTP_DEFAULT_OPTIONS');
                                this.hideItem('SMTP_CUSTOM_OPTIONS');
                            }
                        } else if(id == 'SMTP_CUSTOM_USE') {
                            if(v == 'true') {
                                this.showItem('SMTP_CUSTOM_OPTIONS');
                                this.hideItem('SMTP_DEFAULT_OPTIONS');
                            } else {
                                this.showItem('SMTP_DEFAULT_OPTIONS');
                                this.hideItem('SMTP_CUSTOM_OPTIONS');
                            }
                        }
                    });
                }
            }
        }


            clear();

			var groupArray = [];
			for(var i in tabbarObj.t) {
            	groupArray.push(i);
            }

            dataOutput.setValue("CLIENT_CODE", clientCode);
            dataOutput.setValue("COMPANY_CODE", companyCode);
            dataOutput.setValue("GROUPS", groupArray.join(','));

            doServiceAjax('sepoa.svc.admin.AD_406', 'CONNECTION', 'doQuery', null, function(so) {
                if (so.status != 1) {
                    Alert(Sepoa.cache.text.get('MESSAGE.1002'));
                    return;
                }

                var sf = new SepoaFormater(so.result[0]);
                if (sf.getRowCount() > 0) {
                    var tabs = tabbarObj.getAllTabs();
                    for (var i in tabs) {
                        var formObj = tabbarObj.tabs(tabs[i]).dataObj;
                        if (formObj) {
                            formObj.forEachItem(function(id) {
                                var type = formObj.getItemType(id);
                                if (["block", "fieldset", "container"].indexOf(type) < 0) {
                                    var value = sf.getValue(id, 0);
                                    if (value) {
                                        formObj.setItemValue(id, value);
                                        formObj.callEvent('onChange', [id, value])
                                    }
                                }
                            })
                        }
                    }
                }
            })


dataOutput.setValue("CLIENT_CODE", "");
dataOutput.setValue("COMPANY_CODE", "");
dataOutput.setValue("GROUPS", "");

var tabs = tabbarObj.getAllTabs();
for (var i in tabs) {
    var formObj = tabbarObj.tabs(tabs[i]).dataObj;
    if (formObj) {
        formObj.clear();
    }
}


