            } else if(item.type == 's-kakao-bizplus') {
            	var key = item.name; // GROUP_VENDOR_xxx (ex) KAKAO_BIZPLUS_xxx)
            	var width = item.inputWidth || '';

            	item.type = 'fieldset';
                item.inputWidth = 'auto';
                item.list=[
                    {
