                        name: key + '_SENDER_KEY',
                        label:Sepoa.cache.text.get('AD_406.'+ key +'_SENDER_KEY'),
                        inputWidth: 256
                    }
                ]
            } else if(item.type == 's-kakao-custom') {
                item.type = 'fieldset';
                item.inputWidth = 'auto';
                item.list = [
                    {
                        type: 'input',
                        name: 'KAKAO_CUSTOM_INFO',
                        inputWidth: 256
                    }
                ]
            }

            if(item.list){
                for (var i in item.list) {
                    formOptionBuilder(item.list[i]);
                }
            }


	Confirm(Sepoa.cache.text.get('BASE_MESSAGE.0001'), function(result) {
